#include <iostream>
#include <stdexcept>

int divide(int a, int b) {
    if (b == 0) {
        throw std::runtime_error("division by zero");
    }
    return a / b;
}

int main() {
    int a, b;
    std::cin >> a >> b;
    try {
        std::cout << divide(a, b) << "\n";
    } catch (const std::runtime_error& err) {
        std::cout << "error: " << err.what() << "\n";
    }
    return 0;
}

