go.solution:
package main

import (
	"errors"
	"fmt"
)

func divide(a int, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("division by zero")
	}
	return a / b, nil
}

func main() {
	var a, b int
	fmt.Scan(&a, &b)
	q, err := divide(a, b)
	if err != nil {
		fmt.Println("error:", err)
		return
	}
	fmt.Println(q)
}
